use crate::wasi::clocks::wall_clock;

struct Node;

/// 9999-12-31T23:59:59Z, the last instant whose ISO date is 10 characters.
const MAX_SECS: u64 = 253_402_300_799;

/// Format seconds since the Unix epoch as a UTC `YYYY-MM-DD` string.
/// Always returns exactly 10 characters: input is clamped to year 9999.
fn civil_date(secs: u64) -> String {
    let secs = secs.min(MAX_SECS);
    let z = (secs / 86_400) as i64 + 719_468;
    let era = (if z >= 0 { z } else { z - 146_096 }) / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        // One clock read, so `date` and `started` describe the same instant.
        let now = wall_clock::now();
        RunInfo {
            date: civil_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
